def orient(shape, rot, refl):
 pts=list(shape)
 if refl: pts=[(y,-x) for y,x in pts]
 for _ in range(rot): pts=[(x,-y) for y,x in pts]
 my=min(y for y,x in pts); mx=min(x for y,x in pts)
 return frozenset((y-my,x-mx) for y,x in pts)
